from builtins import str
from builtins import object
import telnetlib

from ute_common_store.store import Store
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str, encode_str

logger = BackgroundLogger.Instance()


class TelnetController(object):
    store = Store()

    def __init__(self):
        pass

    def establish_telnet_connection_with_host(self, host_details, timeout, alias):
        """
        Creates a session with the host, specified by host_details
        @param host_details: dict, connection details to the host
        @param timeout: int, execution timeout. Default 30
        @param alias: string, Execution context/. Default 'default'
        @return:
        @raise Exception

        """
        logger.info(host_details)
        try:
            self._verify_if_telnet_session_for_alias_exists(alias)
            telnet_session = self._get_telnet_session_object(host_details["ip"],
                                                             host_details["user"],
                                                             host_details["password"],
                                                             host_details["prompt"], timeout)
            logger.info("{0} Telnet session opened".format(alias))
            host_details["session_object"] = telnet_session
            logger.info("######### host_details {}".format(host_details))
            self.store.add(host_details, alias=alias)
        except Exception as error:
            logger.error('Unable To Telnet {0}\nError :: {1}'.format(host_details["ip"], error))

    def setup_telnet_remote_access(self, host, user, password, prompt='#', timeout=30,
                                   alias='default', port=0):
        """
        Setup telnet remote access

        @param host: ip to connect to host
        @param user: string, username
        @param password: string, password
        @param prompt: string, Telnet console prompt. Default '#'
        @param timeout: int, execution timeout. Default '30'
        @param alias: string, Execution context. Default 'default'
        @param port: int, port, Default 0
        @return:
        @raise Exception

        """
        try:
            session_dict = {}
            self._verify_if_telnet_session_for_alias_exists(alias)
            telnet_session = self._get_telnet_session_object(host, user, password, prompt, timeout,
                                                             port)
            session_dict["session_object"] = telnet_session
            self.store.add(session_dict, alias=alias)
            logger.info("{0} Telnet session opened".format(alias))
        except Exception as error:
            logger.error('Unable To Telnet {0}\nError :: {1}'.format(host, error))

    def execute_command_on_host(self, command, timeout=10, prompt="#", alias="default"):
        """
        Executes given command on the session specified by the alias
        @param command: string, command to be executed.
        @param prompt: string, Telnet console prompt. Default '#'
        @param timeout: int, execution timeout. Default '30'
        @param alias: string, Execution context. Default 'default'
        @return: Returns string, Shell command output.
        @raise Exception

        """
        try:
            telnet_session = self.store.get(alias)["session_object"]
            telnet_session.set_debuglevel(10)
            telnet_session.write(encode_str(command) + b"\r\n")
            output = telnet_session.read_until(encode_str(prompt), timeout=timeout)
        except Exception as error:
            logger.error('command execution failed :: {0}\nError :: {1}'.format(command, error))
        else:
            return decode_str(output)

    def close_telnet_session_with_host(self, alias):
        """
        Closes an open connection with reference to given alias
        @param alias: string, Execution context. Default 'default'
        @raise Exception
        """
        self.teardown_telnet_remote_access(alias=alias)

    def teardown_telnet_remote_access(self, alias="default"):
        """
        Closes an open connection with reference to given alias
        @param alias: string, Execution context. Default 'default'
        @raise Exception
        """
        try:
            telnet_session = self.store.get(alias)["session_object"]
            telnet_session.close()
            logger.info("{0} Telnet session closed".format(alias))
        except Exception as e:
            logger.error("Exception while closing Telnet connection {}".format(e))
        finally:
            self.store.remove(alias)

    def _verify_if_telnet_session_for_alias_exists(self, alias):
        try:
            if self.store.get(alias):
                logger.error("Telnet session exists for alias {0}".format(alias))
        except Exception as error:
            logger.debug("Telnet session issue {}".format(error))
            return

    def _get_telnet_session_object(self, host, user, password, prompt='#', timeout=30, port=0):
        prompt = encode_str(prompt)
        telnet_session = telnetlib.Telnet(str(host), port)
        telnet_session.read_until(prompt)
        telnet_session.write((encode_str(user) + b'\r') + b"\n")
        telnet_session.read_until(prompt)
        telnet_session.write((encode_str(password) + b'\r') + b"\n")
        telnet_session.read_until(prompt)
        return telnet_session
